   223  /* PEEK_CHAR(dest, tok) macro:
   224   *   Peeks at the current char and stores it in dest.
   225   *   Returns 1 on success, sets tok->err and returns 0 if no more chars.
   226   *   Implicit inputs:  str, len vars
   227   */
   228  #define PEEK_CHAR(dest, tok)                                                 \
   229          (((tok)->char_offset == len)                                         \
   230               ? (((tok)->depth == 0 && state == json_tokener_state_eatws &&   \
   231                   saved_state == json_tokener_state_finish)                   \
   232                      ? (((tok)->err = json_tokener_success), 0)               \
   233                      : (((tok)->err = json_tokener_continue), 0))             \
   234               : (((tok->flags & JSON_TOKENER_VALIDATE_UTF8) &&                \
   235                   (!json_tokener_validate_utf8(*str, nBytesp)))               \
   236                      ? ((tok->err = json_tokener_error_parse_utf8_string), 0) \
   237                      : (((dest) = *str), 1)))
