   241   *   For convenience of existing conditionals, returns the old value of c (0 on eof)
   242   *   Implicit inputs:  c var
   243   */
   244  #define ADVANCE_CHAR(str, tok) (++(str), ((tok)->char_offset)++, c)
   245
