    54  /**
    55   * Extend the buffer p so it has a size of at least min_size.
    56   *
    57   * If the current size is large enough, nothing is changed.
    58   *
    59   * Note: this does not check the available space!  The caller
    60   *  is responsible for performing those calculations.
    61   */
    62  static int printbuf_extend(struct printbuf *p, int min_size)
    63  {
    64          char *t;
    65          int new_size;
    66
    67          if (p->size >= min_size)
    68                  return 0;
    69          /* Prevent signed integer overflows with large buffers. */
    70          if (min_size > INT_MAX - 8)
    71                  return -1;
    72          if (p->size > INT_MAX / 2)
    73                  new_size = min_size + 8;
    74          else {
    75                  new_size = p->size * 2;
    76                  if (new_size < min_size + 8)
    77                          new_size = min_size + 8;
    78          }
    79  #ifdef PRINTBUF_DEBUG
    80          MC_DEBUG("printbuf_memappend: realloc "
    81                   "bpos=%d min_size=%d old_size=%d new_size=%d\n",
    82                   p->bpos, min_size, p->size, new_size);
    83  #endif /* PRINTBUF_DEBUG */
    84          if (!(t = (char *)realloc(p->buf, new_size)))
    85                  return -1;
    86          p->size = new_size;
    87          p->buf = t;
    88          return 0;
    89  }
    90
    91  int printbuf_memappend(struct printbuf *p, const char *buf, int size)
    92  {
    93          /* Prevent signed integer overflows with large buffers. */
    94          if (size > INT_MAX - p->bpos - 1)
    95                  return -1;
    96          if (p->size <= p->bpos + size + 1)
    97          {
    98                  if (printbuf_extend(p, p->bpos + size + 1) < 0)
    99                          return -1;
   100          }
   101          memcpy(p->buf + p->bpos, buf, size);
   102          p->bpos += size;
   103          p->buf[p->bpos] = '\0';
   104          return size;
   105  }
   106
   107  int printbuf_memset(struct printbuf *pb, int offset, int charvalue, int len)
   108  {
   109          int size_needed;
   110
   111          if (offset == -1)
   112                  offset = pb->bpos;
   113          /* Prevent signed integer overflows with large buffers. */
   114          if (len > INT_MAX - offset)
   115                  return -1;
   116          size_needed = offset + len;
   117          if (pb->size < size_needed)
   118          {
   119                  if (printbuf_extend(pb, size_needed) < 0)
   120                          return -1;
   121          }
   122
   123          memset(pb->buf + offset, charvalue, len);
   124          if (pb->bpos < size_needed)
   125                  pb->bpos = size_needed;
   126
   127          return 0;
   128  }
