   130  int sprintbuf(struct printbuf *p, const char *msg, ...)
   131  {
   132          va_list ap;
   133          char *t;
   134          int size;
   135          char buf[128];
   136
   137          /* user stack buffer first */
   138          va_start(ap, msg);
   139          size = vsnprintf(buf, 128, msg, ap);
   140          va_end(ap);
   141          /* if string is greater than stack buffer, then use dynamic string
   142           * with vasprintf.  Note: some implementation of vsnprintf return -1
   143           * if output is truncated whereas some return the number of bytes that
   144           * would have been written - this code handles both cases.
   145           */
   146          if (size == -1 || size > 127)
   147          {
   148                  va_start(ap, msg);
   149                  if ((size = vasprintf(&t, msg, ap)) < 0)
   150                  {
   151                          va_end(ap);
   152                          return -1;
   153                  }
   154                  va_end(ap);
   155                  printbuf_memappend(p, t, size);
   156                  free(t);
   157                  return size;
   158          }
   159          else
   160          {
   161                  printbuf_memappend(p, buf, size);
   162                  return size;
   163          }
   164  }
