   158  // Clear the re-serialization information that the tokener
   159  // saves to ensure that the output reflects the actual
   160  // values we parsed, rather than just the original input.
   161  static void do_clear_serializer(json_object *jso)
   162  {
   163          json_c_visit(jso, 0, clear_serializer, NULL);
   164  }
   165
   166  static int clear_serializer(json_object *jso, int flags, json_object *parent_jso,
   167                              const char *jso_key, size_t *jso_index, void *userarg)
   168  {
   169          if (jso)
   170                  json_object_set_serializer(jso, NULL, NULL, NULL);
   171          return JSON_C_VISIT_RETURN_CONTINUE;
   172  }
